func TestEnumTenDlcCampaignUpdateRequestUsecase(t *testing.T) {
	t.Run("NewFromString_CUSTOMER_CARE", func(t *testing.T) {
		t.Parallel()
		val, err := NewTenDlcCampaignUpdateRequestUsecaseFromString("CUSTOMER_CARE")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TenDlcCampaignUpdateRequestUsecase("CUSTOMER_CARE"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_MARKETING", func(t *testing.T) {
		t.Parallel()
		val, err := NewTenDlcCampaignUpdateRequestUsecaseFromString("MARKETING")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TenDlcCampaignUpdateRequestUsecase("MARKETING"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_ACCOUNT_NOTIFICATION", func(t *testing.T) {
		t.Parallel()
		val, err := NewTenDlcCampaignUpdateRequestUsecaseFromString("ACCOUNT_NOTIFICATION")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TenDlcCampaignUpdateRequestUsecase("ACCOUNT_NOTIFICATION"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_FRAUD_ALERT", func(t *testing.T) {
		t.Parallel()
		val, err := NewTenDlcCampaignUpdateRequestUsecaseFromString("FRAUD_ALERT")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TenDlcCampaignUpdateRequestUsecase("FRAUD_ALERT"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_PUBLIC_SERVICE_ANNOUNCEMENT", func(t *testing.T) {
		t.Parallel()
		val, err := NewTenDlcCampaignUpdateRequestUsecaseFromString("PUBLIC_SERVICE_ANNOUNCEMENT")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TenDlcCampaignUpdateRequestUsecase("PUBLIC_SERVICE_ANNOUNCEMENT"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_SECURITY_ALERT", func(t *testing.T) {
		t.Parallel()
		val, err := NewTenDlcCampaignUpdateRequestUsecaseFromString("SECURITY_ALERT")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TenDlcCampaignUpdateRequestUsecase("SECURITY_ALERT"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewTenDlcCampaignUpdateRequestUsecaseFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewTenDlcCampaignUpdateRequestUsecaseFromString("CUSTOMER_CARE")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}
